INSERT INTO "Skill" (id, key, area, stage, title, description, "evidenceType", "isCore", "isActive", "sortOrder") VALUES ('skill_pre_first_aid', 'pre-first-aid', 'prereq_certs', 0, 'First aid certificate', 'Holds a current UK first aid certificate (Emergency First Aid at Work or equivalent). Renew before expiry.', 'certificate', true, true, 0) ON CONFLICT (key) DO UPDATE SET area = EXCLUDED.area, stage = EXCLUDED.stage, title = EXCLUDED.title, description = EXCLUDED.description, "evidenceType" = EXCLUDED."evidenceType", "isCore" = EXCLUDED."isCore", "isActive" = true, "sortOrder" = EXCLUDED."sortOrder";
INSERT INTO "Skill" (id, key, area, stage, title, description, "evidenceType", "isCore", "isActive", "sortOrder") VALUES ('skill_pre_infection_control', 'pre-infection-control', 'prereq_certs', 0, 'Infection control training', 'Completed a recognised infection prevention and control course for tattooing and piercing (Level 2 or equivalent), covering blood-borne viruses, decontamination and sharps.', 'certificate', true, true, 1) ON CONFLICT (key) DO UPDATE SET area = EXCLUDED.area, stage = EXCLUDED.stage, title = EXCLUDED.title, description = EXCLUDED.description, "evidenceType" = EXCLUDED."evidenceType", "isCore" = EXCLUDED."isCore", "isActive" = true, "sortOrder" = EXCLUDED."sortOrder";
INSERT INTO "Skill" (id, key, area, stage, title, description, "evidenceType", "isCore", "isActive", "sortOrder") VALUES ('skill_pre_bbv', 'pre-bbv', 'prereq_certs', 0, 'Blood-borne viruses', 'Can explain hepatitis B and C, HIV and MRSA: how they spread, how the studio prevents exposure, what to do after an exposure, and when an incident must be reported under RIDDOR.', 'written', true, true, 2) ON CONFLICT (key) DO UPDATE SET area = EXCLUDED.area, stage = EXCLUDED.stage, title = EXCLUDED.title, description = EXCLUDED.description, "evidenceType" = EXCLUDED."evidenceType", "isCore" = EXCLUDED."isCore", "isActive" = true, "sortOrder" = EXCLUDED."sortOrder";
INSERT INTO "Skill" (id, key, area, stage, title, description, "evidenceType", "isCore", "isActive", "sortOrder") VALUES ('skill_pre_hep_b', 'pre-hep-b', 'prereq_certs', 0, 'Hepatitis B vaccination', 'Hepatitis B vaccination course started with the GP or occupational health, with the record on file; an antibody (titre) check where advised.', 'certificate', true, true, 3) ON CONFLICT (key) DO UPDATE SET area = EXCLUDED.area, stage = EXCLUDED.stage, title = EXCLUDED.title, description = EXCLUDED.description, "evidenceType" = EXCLUDED."evidenceType", "isCore" = EXCLUDED."isCore", "isActive" = true, "sortOrder" = EXCLUDED."sortOrder";
INSERT INTO "Skill" (id, key, area, stage, title, description, "evidenceType", "isCore", "isActive", "sortOrder") VALUES ('skill_pre_council', 'pre-council', 'prereq_certs', 0, 'Council registration', 'Registered as a tattooist with the local council before any work on a member of the public, with the certificate on file. Apprentices must not tattoo clients until this is done.', 'certificate', true, true, 4) ON CONFLICT (key) DO UPDATE SET area = EXCLUDED.area, stage = EXCLUDED.stage, title = EXCLUDED.title, description = EXCLUDED.description, "evidenceType" = EXCLUDED."evidenceType", "isCore" = EXCLUDED."isCore", "isActive" = true, "sortOrder" = EXCLUDED."sortOrder";
