INSERT INTO "Skill" (id, key, area, stage, title, description, "evidenceType", "isCore", "isActive", "sortOrder") VALUES ('skill_pre_tests', 'pre-tests', 'prereq_tests', 0, 'Studio knowledge tests', 'Passes the studio''s front-of-house, jewellery, tattoo, piercing and booking tests.', 'written', true, true, 11) ON CONFLICT (key) DO UPDATE SET area = EXCLUDED.area, stage = EXCLUDED.stage, title = EXCLUDED.title, description = EXCLUDED.description, "evidenceType" = EXCLUDED."evidenceType", "isCore" = EXCLUDED."isCore", "isActive" = true, "sortOrder" = EXCLUDED."sortOrder";
