INSERT INTO "Skill" (id, key, area, stage, title, description, "evidenceType", "isCore", "isActive", "sortOrder") VALUES ('skill_hyg_personal', 'hyg-personal', 'hygiene', 1, 'Personal hygiene standards', 'Short clean nails, hair tied back, lotion use, and covering cuts, hangnails and any non-intact skin with a waterproof dressing.', NULL, true, true, 13) ON CONFLICT (key) DO UPDATE SET area = EXCLUDED.area, stage = EXCLUDED.stage, title = EXCLUDED.title, description = EXCLUDED.description, "evidenceType" = EXCLUDED."evidenceType", "isCore" = EXCLUDED."isCore", "isActive" = true, "sortOrder" = EXCLUDED."sortOrder";
